-- (§7.13, monthly partitions, as audit_events in 0003), which Drizzle can't declare. Its
-- partitions are made in 0040 by kept.ensure_llm_partitions().
CREATE TABLE "ai_breakers" (
	"provider_id" uuid PRIMARY KEY NOT NULL,
	"reason" text,
	"until" timestamp with time zone,
	"trips" integer DEFAULT 0 NOT NULL,
	"recent_errors" timestamp with time zone[] DEFAULT '{}'::timestamptz[] NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ai_breakers_reason_chk" CHECK ("reason" IN ('rate_limited', 'quota', 'auth', 'provider_down')),
	CONSTRAINT "ai_breakers_trip_pair_chk" CHECK ((reason IS NULL) = (until IS NULL)),
	CONSTRAINT "ai_breakers_trips_chk" CHECK (trips >= 0)
);
