CREATE TABLE "ai_budgets" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"scope" text NOT NULL,
	"owner_account_id" uuid,
	"location_id" uuid,
	"user_id" uuid,
	"task" text,
	"tokens_per_minute" integer,
	"tokens_per_day" integer,
	"tokens_per_month" bigint,
	"monthly_cap_amount" numeric(16, 4),
	"cap_currency" char(3),
	"paused_until" timestamp with time zone,
	"paused_reason" text,
	"warned_80_month" date,
	"warned_100_month" date,
	"set_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"row_version" integer DEFAULT 1 NOT NULL,
	"change_seq" bigint,
	CONSTRAINT "ai_budgets_scope_uq" UNIQUE NULLS NOT DISTINCT("scope","owner_account_id","location_id","user_id","task"),
	CONSTRAINT "ai_budgets_scope_chk" CHECK ("scope" IN ('instance', 'instance_account', 'account', 'location', 'member', 'user')),
	CONSTRAINT "ai_budgets_task_chk" CHECK ("task" IN ('extraction', 'assistant', 'embeddings')),
	CONSTRAINT "ai_budgets_paused_reason_chk" CHECK ("paused_reason" IN ('manual', 'cap_money', 'cap_tokens', 'tokens_day')),
	CONSTRAINT "ai_budgets_tpm_chk" CHECK (tokens_per_minute > 0),
	CONSTRAINT "ai_budgets_tpd_chk" CHECK (tokens_per_day > 0),
	CONSTRAINT "ai_budgets_month_tokens_chk" CHECK (tokens_per_month > 0),
	CONSTRAINT "ai_budgets_money_chk" CHECK (monthly_cap_amount >= 0),
	CONSTRAINT "ai_budgets_money_pair_chk" CHECK ((monthly_cap_amount IS NULL) = (cap_currency IS NULL)),
	CONSTRAINT "ai_budgets_pause_pair_chk" CHECK ((paused_until IS NULL) = (paused_reason IS NULL)),
	CONSTRAINT "ai_budgets_scope_ids_chk" CHECK (CASE scope
            WHEN 'instance' THEN owner_account_id IS NULL AND location_id IS NULL AND user_id IS NULL
            WHEN 'instance_account' THEN location_id IS NULL AND user_id IS NULL
            WHEN 'account' THEN owner_account_id IS NOT NULL AND location_id IS NULL AND user_id IS NULL
            WHEN 'location' THEN owner_account_id IS NOT NULL AND location_id IS NOT NULL AND user_id IS NULL
            WHEN 'member' THEN owner_account_id IS NOT NULL AND location_id IS NULL AND user_id IS NOT NULL
            ELSE owner_account_id IS NULL AND location_id IS NULL AND user_id IS NOT NULL END),
	CONSTRAINT "ai_budgets_minute_day_chk" CHECK ((tokens_per_minute IS NULL AND tokens_per_day IS NULL)
          OR (scope IN ('instance', 'account') AND task IS NOT NULL))
);
