	"request_id" text NOT NULL,
	"attempt" smallint DEFAULT 1 NOT NULL,
	"task" text NOT NULL,
	"budget_task" text GENERATED ALWAYS AS (CASE WHEN task LIKE 'extract\_%' THEN 'extraction'
               WHEN task LIKE 'assistant\_%' THEN 'assistant'
               WHEN task LIKE 'embed\_%' THEN 'embeddings' ELSE 'test' END) STORED,
	"location_id" uuid,
	"owner_account_id" uuid,
	"user_id" uuid,
	"paying_scope" text NOT NULL,
	"paying_account_id" uuid,
	"paying_user_id" uuid,
