	"provider_id" uuid,
	"provider_kind" text NOT NULL,
	"model" text NOT NULL,
	"reasoning" text,
	"prompt_version" text,
	"sent" boolean NOT NULL,
	"estimate_tokens" integer,
	"input_tokens" integer,
	"output_tokens" integer,
	"reasoning_tokens" integer,
	"cached_input_tokens" integer,
	"image_count" smallint DEFAULT 0 NOT NULL,
	"image_tokens_each" integer,
	"image_bytes" integer,
	"attachment_ids" uuid[],
	"latency_ms" integer,
	"finish_reason" text,
	"outcome" text NOT NULL,
	"error_code" text,
	"http_status" smallint,
	"cost_amount" numeric(16, 6),
	"cost_currency" char(3),
	"cost_source" text NOT NULL,
	"price_id" uuid,
	"extraction_id" uuid,
	"thread_id" uuid,
	"thing_id" uuid,
	"rl_remaining_tokens" integer,
	"rl_reset_at" timestamp with time zone,
	CONSTRAINT "llm_calls_pk" PRIMARY KEY("id","at"),
	CONSTRAINT "llm_calls_task_chk" CHECK ("task" IN ('extract_thing', 'extract_receipt', 'extract_label', 'extract_reading', 'assistant_turn', 'assistant_followup', 'embed_thing', 'embed_query', 'connection_test')),
	CONSTRAINT "llm_calls_outcome_chk" CHECK ("outcome" IN ('ok', 'refused', 'rate_limited', 'over_budget', 'provider_error', 'timeout', 'schema_invalid', 'truncated')),
	CONSTRAINT "llm_calls_cost_source_chk" CHECK ("cost_source" IN ('provider', 'price_table', 'price_table_later', 'unknown', 'not_sent')),
	CONSTRAINT "llm_calls_paying_scope_chk" CHECK ("paying_scope" IN ('instance', 'account', 'user')),
	CONSTRAINT "llm_calls_request_id_chk" CHECK (char_length(request_id) <= 64),
	CONSTRAINT "llm_calls_attempt_chk" CHECK (attempt BETWEEN 1 AND 20),
	CONSTRAINT "llm_calls_prompt_version_chk" CHECK (char_length(prompt_version) <= 20),
	CONSTRAINT "llm_calls_image_count_chk" CHECK (image_count >= 0),
	CONSTRAINT "llm_calls_finish_reason_chk" CHECK (char_length(finish_reason) <= 40),
	CONSTRAINT "llm_calls_error_code_chk" CHECK (error_code ~ '^[a-z0-9_]{1,40}$'),
	CONSTRAINT "llm_calls_cost_pair_chk" CHECK ((cost_amount IS NULL) = (cost_currency IS NULL)),
	CONSTRAINT "llm_calls_not_sent_chk" CHECK (sent OR (input_tokens IS NULL AND output_tokens IS NULL AND cost_amount IS NULL)),
	CONSTRAINT "llm_calls_sent_source_chk" CHECK (sent = (cost_source <> 'not_sent')),
	CONSTRAINT "llm_calls_price_chk" CHECK (cost_source NOT IN ('price_table', 'price_table_later') OR price_id IS NOT NULL),
	CONSTRAINT "llm_calls_payer_chk" CHECK (CASE paying_scope
            WHEN 'instance' THEN paying_account_id IS NULL AND paying_user_id IS NULL
            WHEN 'account' THEN paying_account_id IS NOT NULL AND paying_user_id IS NULL
            ELSE paying_user_id IS NOT NULL AND paying_account_id IS NULL END)
) PARTITION BY RANGE ("at");
